contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "not enough ether");

        uint256 before = c.balances(address(this));
        require(before <= type(uint256).max, "impossible");

        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = c.balances(address(this));

        if (before > type(uint256).max - amount) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(afterBal == before + amount);
        }
    }
    receive() external payable {}
}

