    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance");
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }
        uint256 cBalBefore = address(c).balance;
        uint256 toBalBefore = to.balance;
        bool reverted;
        try c.migrateTo(to) { reverted = false; } catch { reverted = true; }
        assert(!reverted && address(c).balance == 0 && to.balance == toBalBefore + cBalBefore);
    }

    receive() external payable {}
}

