contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        uint256 max = type(uint256).max;
        uint256 selfBalBefore = address(this).balance; // remaining balance after value transfer is selfBalBefore - amount
        uint256 cBalBefore = address(c).balance;

        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalAfter = address(c).balance;

        bool overflow = (selfBalBefore < amount) || (address(this).balance > max - amount);
        assert(reverted == overflow);
        assert(cBalAfter == (reverted ? cBalBefore : cBalBefore + amount));
    }

    receive() external payable {}
}

