contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        uint256 max = type(uint256).max;
        uint256 cBalBefore = address(c).balance;

        // Withdraw all existing balance first so the caller's stored balance is 0,
        // making the overflow condition purely amount > max - 0, i.e. impossible.
        // Then deposit the amount once, which must succeed (no overflow from zero).
        c.deposit{value: amount}();

        uint256 cBalAfter = address(c).balance;
        assert(cBalAfter == cBalBefore + amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 dep, uint256 amt) public payable {
        require(dep > 0);
        require(address(this).balance >= dep);
        c.deposit{value: dep}();

        uint256 balBefore = address(c).balance;
        uint256 myBefore = address(this).balance;

        bool reverted;
        try c.withdraw(amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (amt > dep) {
            assert(reverted && address(c).balance == balBefore && address(this).balance == myBefore);
        } else {
            assert(!reverted && address(c).balance == balBefore - amt && address(this).balance == myBefore + amt);
        }
    }

    receive() external payable {}
}

