contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public payable {
        require(address(this).balance >= amount);

        bool depositReverted;
        if (amount > 0) {
            try c.deposit{value: amount}() { depositReverted = false; } catch { depositReverted = true; }
        } else {
            depositReverted = false;
        }

        uint256 beforeTo;
        uint256 beforeC;
        uint256 beforeThis;
        if (!depositReverted) {
            beforeTo = to.balance;
            beforeC = address(c).balance;
            beforeThis = address(this).balance;
        }

        bool reverted;
        try c.migrateTo(to) { reverted = false; } catch { reverted = true; }

        if (!depositReverted) {
            assert(!reverted && address(c).balance == 0 && to.balance == beforeTo + beforeC && address(this).balance == beforeThis);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

